import { isNil } from 'lodash-es';

import { getDatapointIsGap } from '../../core/functions/apply-gap-policy.js';
import { Timeseries } from '../../core/types/timeseries.js';
import {
  SparklineDatapointMetadata,
  SparklineGapPolicy,
} from '../types/sparkline.js';

export const sanitizeSparklineData = (
  series: Timeseries,
  gapPolicy: SparklineGapPolicy,
) => {
  const sanitizedDatapoints: SparklineDatapointMetadata[] = [];
  const sanitizedValues: number[] = [];

  for (let i = 0; i < series.datapoints.length; i++) {
    const currentDatapoint = series.datapoints[i];

    if (!isNil(currentDatapoint.value)) {
      sanitizedDatapoints.push(currentDatapoint);
      sanitizedValues.push(currentDatapoint.value);

      if (gapPolicy === 'gap') {
        let nextDatapoint = series.datapoints[i + 1];

        while (
          (isNil(nextDatapoint) || isNil(nextDatapoint.value)) &&
          i < series.datapoints.length
        ) {
          i++;
          nextDatapoint = series.datapoints[i + 1];
        }

        const isGap = getDatapointIsGap(
          currentDatapoint,
          nextDatapoint,
          gapPolicy,
        );

        if (isGap) {
          const gapDatapoint = {
            start: currentDatapoint.end ?? currentDatapoint.start,
            end: nextDatapoint.start,
            value: Infinity,
            isGap: true,
          };

          sanitizedDatapoints.push(gapDatapoint);
        }
      }
    }
  }

  return {
    sanitizedSeries: { ...series, datapoints: sanitizedDatapoints },
    sanitizedValues,
  };
};
